export function solve(input) {
  const d = input;
  const cells = { ...d.cells };
  const evaluate = (k, active) => {
    if (active.has(k)) return "CYCLE";
    const v = cells[k] ?? 0;
    if (typeof v === "number") return v;
    const next = new Set(active);
    next.add(k);
    let total = 0;
    for (const name of v.sum) {
      const x = evaluate(name, next);
      if (x === "CYCLE") return x;
      total += x;
    }
    return total;
  };
  const out = [];
  for (const op of d.operations) {
    if (op.op === "set") cells[op.cell] = op.value;
    else if (op.op === "get") out.push(evaluate(op.cell, new Set()));
    else {
      const old = cells[op.cell];
      cells[op.cell] = op.value;
      let bad = false;
      for (const k of Object.keys(cells)) if (evaluate(k, new Set()) === "CYCLE") bad = true;
      if (bad) {
        if (old === undefined) delete cells[op.cell];
        else cells[op.cell] = old;
      }
      out.push(!bad);
    }
  }
  return out;
}

